def score_rules(inputs, outputs, rules):
    """Simulate applying rules and return score"""
    # Apply rules in order to each input
    total_correct = 0
    for inp, expected in zip(inputs, outputs):
        current = inp
        for pattern, replacement in rules:
            current = current.replace(pattern, replacement)
        if current == expected:
            total_correct += 1
    return total_correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find inputs that get incorrectly modified"""
    over_apps = []
    for i, (inp, expected) in enumerate(zip(inputs, outputs)):
        current = inp
        for pattern, replacement in rules:
            current = current.replace(pattern, replacement)
        if current != expected:
            over_apps.append((i, inp, current))
    return over_apps

